def solve(n):
    out = 1
    for i in range(2, n + 1):
        out *= i
    return out

def solve(rows):
    out = []
    for row in rows:
        for x in row:
            out = out + [x]
    return out

def solve(xs, k):
    if len(xs) == 0:
        return []
    k = k % len(xs)
    return xs[k:] + xs[:k]

def solve(xs):
    vals = sorted(set(xs))
    if len(vals) < 2:
        return None
    return vals[-2]
